/// The clock is read under the lock. As a default argument it was read
/// before the lock was taken, and this is the busiest cache in the app —
/// eighteen call sites, one of them a default argument in the glyph
/// renderer and so reached once per draw, another `ProviderRegistry.all`,
/// which `rebuildItems` reads twice. A menu bar refresh, the settings
/// panel and the background scan contend for it routinely.
///
/// The cost was worse than a missed cache. `checked` is assigned
/// unconditionally below, so a thread holding a reading older than the
/// entry it found did not merely re-read the folder — it wound `checked`
/// backwards, leaving the next caller likelier to miss as well. Under
/// sustained contention the one-second throttle degraded rather than
/// occasionally slipping, and what it throttles is reading and parsing
/// every descriptor file.
func snapshot(now injected:TimeInterval? = nil,force:Bool = false) -> Snapshot {
    lock.lock(); defer { lock.unlock() }
    let now = injected ?? ProcessInfo.processInfo.systemUptime
    if !force, CacheWindow.isFresh(now: now, stamped: checked, within: 1) { return current }
    checked = now
    do {
        let inventory = try inventory()
        if !force, inventory.stamp == fingerprint,
           current.issues.isEmpty
               || CacheWindow.isFresh(now: now, stamped: loaded, within: 5) { return current }
        var next:[String:HarnessDescriptor] = [:], problems:[String] = [], bytes = 0
        for file in inventory.files {
            guard bytes < 8 * 1_024 * 1_024 else { throw BoundedFile.ReadError.tooLarge }
            let name = file.lastPathComponent
            do {
                let data = try BoundedFile.read(file,maxBytes:1_024 * 1_024)
                bytes += data.count
                guard bytes <= 8 * 1_024 * 1_024 else { throw BoundedFile.ReadError.tooLarge }
                next[name] = try HarnessDocument.decode(data).descriptor
            } catch {
                guard bytes <= 8 * 1_024 * 1_024 else { throw BoundedFile.ReadError.tooLarge }
                next[name] = byFile[name]
                problems.append("A harness file is unreadable or invalid. Its last valid configuration is retained when available.")
            }
        }
        guard try self.inventory().stamp == inventory.stamp else { throw BoundedFile.ReadError.readFailed }
        let grouped = Dictionary(grouping:next.values,by:\.id)
        let previous = Dictionary(uniqueKeysWithValues:current.descriptors.map { ($0.id,$0) })
        var resolved:[HarnessDescriptor] = []
        for (id,descriptors) in grouped {
            if descriptors.count == 1 { resolved.append(descriptors[0]) }
            else {
                if let prior = previous[id] { resolved.append(prior) }
                problems.append("Multiple harness files declare the same ID. The last unambiguous configuration is retained when available.")
            }
        }
        byFile = next
        // The descriptor sort is load-bearing: `resolved` is built by
        // iterating a dictionary, and this order becomes the registry's,
        // which becomes the menu bar's left-to-right. The issue
        // deduplication beside it is not — the `issues` accessor folds and
        // sorts again, so no mutation of that half can be caught.
        current = Snapshot(descriptors:resolved.sorted { $0.id < $1.id },issues:Array(Set(problems)).sorted())
        fingerprint = inventory.stamp; loaded = now
    } catch {
        current.issues = ["The harness folder could not be refreshed within its safety limits. The last valid catalog is retained."]
        fingerprint = nil
    }
    return current
}

